.accordion .accordion-item {
  padding-top: 1rem;
  padding-bottom: 1rem;
}

.accordion .accordion-item:not(:last-child) {
  --tw-border-opacity: 1;
  border-color: rgba(237, 242, 247, var(--tw-border-opacity));
}

.dark .accordion .accordion-item:not(:last-child){
  --tw-border-opacity: 1;
  border-color: rgba(63, 72, 101, var(--tw-border-opacity));
}

.accordion .accordion-item:not(:last-child){
  border-bottom-width: 1px;
}

.accordion .accordion-item:first-child {
  margin-top: -1rem;
}

.accordion .accordion-item:last-child {
  margin-bottom: -1rem;
}

.accordion .accordion-item .accordion-header .accordion-button {
  font-weight: 500;
  text-align: left;
  width: 100%;
}

.accordion .accordion-item .accordion-header .accordion-button:focus {
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.accordion .accordion-item .accordion-header .accordion-button:not(.collapsed) {
  --tw-text-opacity: 1;
  color: rgba(139,21,61, var(--tw-text-opacity));
}

.dark .accordion .accordion-item .accordion-header .accordion-button:not(.collapsed){
  --tw-text-opacity: 1;
  color: rgba(49, 96, 216, var(--tw-text-opacity));
}

.accordion .accordion-collapse {
  line-height: 1.625;
  margin-top: 0.75rem;
  --tw-text-opacity: 1;
  color: rgba(74, 85, 104, var(--tw-text-opacity));
}

.dark .accordion .accordion-collapse{
  --tw-text-opacity: 1;
  color: rgba(113, 128, 150, var(--tw-text-opacity));
}

.accordion .accordion-collapse.collapse:not(.show) {
  display: none;
}

.accordion.accordion-boxed .accordion-item {
  --tw-border-opacity: 1;
  border-color: rgba(237, 242, 247, var(--tw-border-opacity));
}

.dark .accordion.accordion-boxed .accordion-item{
  --tw-border-opacity: 1;
  border-color: rgba(63, 72, 101, var(--tw-border-opacity));
}

.accordion.accordion-boxed .accordion-item{
  border-width: 1px;
  margin-top: 0.75rem;
  padding: 1rem;
}

.accordion.accordion-boxed .accordion-item:first-child {
  margin-top: 0px;
}

.accordion.accordion-boxed .accordion-item:last-child {
  margin-bottom: 0px;
}

.alert {
  border-radius: 0.375rem;
  padding-top: 1rem;
  padding-bottom: 1rem;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
  position: relative;
}

.alert:not(.show) {
  display: none;
}

.alert.alert-dismissible {
  padding-left: 1.25rem;
  padding-right: 4rem;
}

.alert .btn-close {
  border-radius: 0.375rem;
  border-width: 1px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 500;
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
  padding-left: 0.75rem;
  padding-right: 0.75rem;
  --tw-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
  transition-property: background-color, border-color, color, fill, stroke, opacity, box-shadow, transform;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 150ms;
  transition-duration: 200ms;
}

.alert .btn-close:hover {
  --tw-bg-opacity: 0.9;
  --tw-border-opacity: 0.9;
}

.alert .btn-close:focus {
  outline: 2px solid transparent;
  outline-offset: 2px;
  --tw-ring-offset-shadow: var(--tw-ring-inset) 0 0 0 var(--tw-ring-offset-width) var(--tw-ring-offset-color);
  --tw-ring-shadow: var(--tw-ring-inset) 0 0 0 calc(3px + var(--tw-ring-offset-width)) var(--tw-ring-color);
  box-shadow: var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow, 0 0 #0000);
}

.alert .btn-close:not(button) {
  text-align: center;
}

.alert .btn-close{
  border-width: 0px;
  margin-top: auto;
  margin-bottom: auto;
  margin-right: 0.5rem;
  position: absolute;
  right: 0px;
  --tw-shadow: 0 0 #0000;
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}

.alert .btn-close:focus {
  --tw-ring-offset-shadow: var(--tw-ring-inset) 0 0 0 var(--tw-ring-offset-width) var(--tw-ring-offset-color);
  --tw-ring-shadow: var(--tw-ring-inset) 0 0 0 calc(0px + var(--tw-ring-offset-width)) var(--tw-ring-color);
  box-shadow: var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow, 0 0 #0000);
}

