/* @start LABEL */

.tail-select .select-label {
  cursor: pointer;
  color: rgba(48, 52, 56, 0.85);
  width: 100%;
  margin: 0;
  padding: 5px 30px 5px 10px;
  display: block;
  z-index: 27;
  position: relative;
  text-align: left;
  background-color: white;
  border-width: 0px;
  border-style: solid;
