}

.tail-select.active .select-label:after {
  opacity: 0.85;
  transform: rotate(180deg);
  -moz-transform: rotate(180deg);
  -webkit-transform: rotate(180deg);
}

.tail-select.disabled .select-label {
  cursor: not-allowed;
